effect.shader:
const float PI = 3.14159265359;
void main() {
vec2 uv = acScreenNorm - 0.5;
float aspect = acScreenSize.x / acScreenSize.y;
uv.x *= aspect;
float dist = length(uv);
float angle = atan(uv.y, uv.x);
float radius = size / 100.0;
if (dist > radius) {
gl_FragColor = vec4(0.0);
return;
}
float normalizedDist = dist / radius;
float z = sqrt(1.0 - normalizedDist * normalizedDist);
float r = atan(normalizedDist, z * convergence) / PI;
r *= 2.0;
vec2 newUV;
newUV.x = r * cos(angle);
newUV.y = r * sin(angle);
newUV.x /= aspect;
newUV += 0.5;
gl_FragColor = texture2DCv(inputImg.texture, newUV);
}
